R,C=17,19
g=[[0]*C for _ in range(R)]
threes=[(3,4),(8,11),(13,6)]
for r,c in threes:
    for cc in range(c-2,c+3):
        if 0<=r-2<R: g[r-2][cc]=5
    for rr in range(r-1,r+2):
        for cc in (c-2,c+2):
            if 0<=rr<R and 0<=cc<C: g[rr][cc]=2
    g[r-1][c]=5
    g[r][c]=3
    for cc in range(C): g[r+2][cc]=2
    for cc in range(c-2,c+3): g[r+2][cc]=8
for row in g: print(row)
